select tc.*, u.id createByUserId, u.name createByUserName
from t_clue tc left join t_user u on tc.create_by = u.id
where tc.id = #{id}

select tc.*, u.id createByUserId, u.name createByUserName, tcust.id linked_customer_id
from t_clue tc
  left join t_user u on tc.create_by = u.id
  left join t_customer tcust on tcust.clue_id = tc.id


    and tc.name like concat('%',#{search.name},'%')
    and tc.phone like concat('%',#{search.phone},'%')
    and tc.intention_course like concat('%',#{search.intentionCourse},'%')
    and tc.source like concat('%',#{search.source},'%')
    and tc.remark like concat('%',#{search.remark},'%')
    and tc.clue_status = #{search.clueStatus}
    and tc.create_by = #{search.createBy}
    and tc.create_time >= #{search.createTimeStart}
    and tc.create_time <= #{search.createTimeEnd}
    and tc.create_time <= #{search.createTimePoint}
    and tc.create_time >= #{search.createTimePoint}
    and tc.trial_class_time >= #{search.trialClassTimeStart}
    and tc.trial_class_time <= #{search.trialClassTimeEnd}
    and tc.trial_class_time <= #{search.trialClassTimePoint}
    and tc.trial_class_time >= #{search.trialClassTimePoint}
    and tc.age = #{search.ageValue}
    and tc.age > #{search.ageValue}
    and tc.age < #{search.ageValue}
    and tc.age between #{search.ageMin} and #{search.ageMax}
    and tc.intention_strength = #{search.intentionStrengthValue}
    and tc.intention_strength > #{search.intentionStrengthValue}
    and tc.intention_strength < #{search.intentionStrengthValue}
    and tc.intention_strength between #{search.intentionStrengthMin} and #{search.intentionStrengthMax}


    ${baseQuery.filterSQL}


order by (tc.clue_status = '已转客户') asc,
         tc.intention_strength is null, tc.intention_strength desc,
         tc.trial_class_time is null, tc.trial_class_time asc,
         tc.id desc

